package net.officefloor.hq.app.statement;

import java.sql.Date;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of statements, kept per sheet. */
@Repository
public class Statements {

    private final JdbcTemplate jdbc;

    public Statements(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Locks the person's row until the transaction commits, so two statements of them are taken one after the other. */
    public void lock(long personId) {
        jdbc.queryForList("SELECT id FROM person WHERE id = ? FOR UPDATE", personId);
    }

    public void add(Statement statement) {
        jdbc.update("INSERT INTO statement (sheet_id, person_id, due_total, claims, stated_on) VALUES (?, ?, ?, ?, ?)",
                statement.sheetId(), statement.personId(), statement.dueTotal(), statement.claims(),
                Date.valueOf(statement.statedOn()));
    }

    /** Removes the person's last statement and returns it; null when they have none. */
    public CancelledStatement removeLast(String sheetId, long personId) {
        List<Map<String, Object>> last = jdbc.queryForList("SELECT id, due_total FROM statement "
                + "WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 1", sheetId, personId);
        if (last.isEmpty()) {
            return null;
        }
        jdbc.update("DELETE FROM statement WHERE id = ?", last.get(0).get("id"));
        return new CancelledStatement((String) last.get(0).get("due_total"));
    }

    /** Each person of the sheet who has a statement: their count, and their last statement's due-total and date. */
    public List<StatementResponse> list(String sheetId) {
        return jdbc.query("SELECT s.person_id, c.n, s.due_total, s.stated_on FROM statement s "
                + "JOIN (SELECT person_id, COUNT(*) AS n, MAX(id) AS last_id FROM statement WHERE sheet_id = ? "
                + "GROUP BY person_id) c ON s.id = c.last_id ORDER BY s.person_id",
                (rs, n) -> new StatementResponse(rs.getLong(1), rs.getInt(2), rs.getString(3),
                        rs.getDate(4).toLocalDate().toString()),
                sheetId);
    }

    public StatementResponse find(String sheetId, long personId) {
        return list(sheetId).stream().filter(s -> s.personId() == personId).findFirst()
                .orElse(new StatementResponse(personId, 0, null, null));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class TakeStatement {
    // Records the person's due-total now (a deferred claim counts in none and is left unbound) (held to the sheet's cap) and binds each of their counting claims (their open claims within a hold and not bound do not count) to its figure now;
    // the rest of their claims are left unbound. The late charge is never bound: the due-total includes it,
    // but each claim is bound to the figure under it.
    public void take(@Val Person person, Claims claims, Rates rates, Settings settings, Sheets sheets, Statements statements,
            Out<Statement> statementOut) {
        statements.lock(person.id());
        LocalDate today = sheets.today(person.sheetId());
        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.list(person.sheetId())) {
            if (claim.personId() == person.id()
                    && (claim.status() == ClaimStatus.SETTLED || (claim.status().isOpen() && Rollup.counts(claim, person, today)))) {
                BigDecimal figure = figure(claim, person, rates, settings);
                figures.put(claim.id(), figure);
                BigDecimal due = claim.settledDue() != null ? figure : settings.withLate(claim, figure, today);
                if (due != null) {
                    total = total.add(due);
                }
            }
        }
        // With no rate today and no figure, the due-total is n/a.
        boolean none = rates.on(person.sheetId(), person.gradeOn(today), today) == null
                && figures.values().stream().allMatch(Objects::isNull);
        claims.bind(person.sheetId(), person.id(), figures);
        Statement statement = new Statement(person.sheetId(), person.id(),
                none ? "n/a" : settings.capped(person.sheetId(), total).toPlainString(),
                figures.size(), today);
        statements.add(statement);
        statementOut.set(statement);
    }

    /**
     * The claim's figure now (null when it has none): a settled claim's frozen due, otherwise the figure the
     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date (not floored: the floor goes on last, after the late charge).
     */
    private static BigDecimal figure(Claim claim, Person person, Rates rates, Settings settings) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
        return settings.live(claim, rate);
    }
}
