content.content:
-- Who opened the claim: the signed-in user named by the open. Null for a claim never opened.
-- The user who opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- The version of a person, raised on every edit. An edit names the version its form loaded and is
-- refused when the person has been saved since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- A claim bound by its person's last statement: stated, at the figure it had then (stated_due; null when it
-- had none). It shows and totals that figure until the person's next statement, which rebinds every claim
-- of theirs that counts then and leaves the rest unbound.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
-- The statements taken of a person, in the order taken (by id): their due-total then ("n/a" when it had
-- none), how many of their claims counted, and the sheet's today when it was taken.
CREATE TABLE statement (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255) NOT NULL,
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    due_total  VARCHAR(32)  NOT NULL,
    claims     INT          NOT NULL,
    stated_on  DATE         NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
-- A sheet's periods: a name unique on the sheet and a from and to date, inclusive. No two periods
-- of a sheet overlap (checked when one is added).
CREATE TABLE period (
    sheet_id  VARCHAR(255) NOT NULL,
    name      VARCHAR(255) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date),
    PRIMARY KEY (sheet_id, name)
);
-- A period can be closed. Closing fixes its due-total at that moment: closed_total is that figure
-- (null while the period is open), and later changes to rates do not alter it.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
-- The date a person is retired from (null when not retired). A person with one set counts as retired
-- at once, whatever the date; claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own, the
-- sheet's or a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
-- A sheet's settings, one value per key (clerk-limit: an amount with two decimals). A key with no
-- row, or a blank value, is not set (a clerk limit not set is no limit).
CREATE TABLE setting (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key)
);
-- The role a sheet gives a user name: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
-- The people a person names as their patrons: other people on the same sheet, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL,
    patron_id BIGINT NOT NULL,
    PRIMARY KEY (person_id, patron_id)
);
-- A person's grade is dated: person.grade is the first grade they were given, which applies from the
-- beginning of time; each row here is a grade they were given from a date on. At most one per date.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL,
    from_date DATE       NOT NULL,
    grade     VARCHAR(1) NOT NULL,
    PRIMARY KEY (person_id, from_date)
);
-- A sheet's own settings. A sheet with no row here has never been changed: its today is the real date.
CREATE TABLE sheet (
    id         VARCHAR(255) PRIMARY KEY,
    today_date DATE NOT NULL
);
-- A correction (a claim with a negative amount) names, by number, the SETTLED claim of the same person it
-- corrects; null for any other claim. The amount's old "0 or more" check (unnamed) goes with its column, which is
-- rebuilt so that only a correction may be negative.
ALTER TABLE claim ADD COLUMN corrects BIGINT;
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(15, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
-- A claim's number becomes text: the sheet-wide 1, 2, ... or, while the sheet numbers by period, <period>-<n>
-- (X-<n> for a claim in no period). A correction names the number it corrects the same way.
-- claim_period_number_seq holds the last number each sheet gave in each period ('' is the no-period sequence).
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(300);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(300);
CREATE TABLE claim_period_number_seq (
    sheet_id    VARCHAR(255) NOT NULL,
    scope       VARCHAR(255) NOT NULL,
    last_number BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, scope)
);
-- Where a claim stands in its sheet's newest-first list: the next on its sheet when it is made, and again
-- when it is reassigned to another person, so a moved claim lists as its new person's newest whatever its date.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- A claim's due-by, fixed when it is made: its date plus the terms of its person's grade on that date
-- (the sheet's terms when the grade has none of its own). Claims made before terms were kept per grade
-- are due by their date plus the sheet's terms (14 when never set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM setting s
    WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms' AND s.setting_value <> ''), 14), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
