package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHold {

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // A blank from-date takes the sheet's today (filled in when stored); a blank to-date leaves the hold open-ended.
    // A to-date before the from-date is checked once the from-date is known.
    public void validate(@RequestBody HoldRequest body, Out<HoldDates> dates) throws InvalidPersonException {
        LocalDate from = parse(body == null ? null : body.from());
        LocalDate to = parse(body == null ? null : body.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidPersonException("The to-date is before the from-date.");
        }
        dates.set(new HoldDates(from, to));
    }

    private static LocalDate parse(String value) throws InvalidPersonException {
        String raw = value == null ? "" : value.trim();
        if (raw.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(raw, ISO);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.person;

/** The body of a hold: its from-date and to-date, yyyy-mm-dd; a blank from-date is the sheet's today, a blank to-date has no end. */
public record HoldRequest(String from, String to) {
}
# PUT /api/sheets/{sheetId}/people/{personId}/hold — add a hold to a person. Body
# {"from":"yyyy-mm-dd","to":"yyyy-mm-dd"}; a blank from-date is the sheet's today, a blank to-date has no
# end (a hold ends on its to-date). Their OPEN claims dated within a hold and not bound by a statement
# count in no live total. A date that is not real, or a to-date before the from-date, is refused with 400
# and nothing is stored; 404 for a person not on the sheet.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: hold
  govern: [ transaction ]
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.person.AuditPersonHeld
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithEditedPerson
  govern: [ transaction ]
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

public class RefuseArchived {
    // An archived sheet keeps everything visible and changes nothing: every write is refused before anything is read, stored or recorded.
    public void refuse(@PathVariable("sheetId") String sheetId, Sheets sheets) throws SheetArchivedException {
        if (sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException("The sheet is archived: it can change nothing.");
        }
    }
}
